/**
Check if the provided email address is valid. For example, abc.123@def.ghi.com.uk is a valid email address. Cover as many cases as possible to avoid false negatives.

@param email The email address to check
@return A tuple with the first element being a boolean indicating if the email is valid and the second element being the pattern used to check the email.
*/
std::tuple<bool, std::string> check_email(const std::string& email) {
    // This regex aims to be comprehensive for common email formats,
    // balancing RFC compliance with practical usability and avoiding
    // overly complex patterns that could lead to ReDoS vulnerabilities.
    // It allows for:
    // - Local part:
    //   - Alphanumeric characters, ., _, +, -
    //   - Dots are not allowed at the beginning or end, and not consecutively.
    //   - Supports quoted local parts with more special characters.
    // - Domain part:
    //   - Standard domain names with alphanumeric characters and hyphens.
    //   - Hyphens are not allowed at the beginning or end of domain labels.
    //   - Supports subdomains.
    //   - Top-level domains (TLDs) are at least two characters long.
    //
    // Note: Perfect email validation with a single regex is extremely difficult
    // due to the complexity of RFC specifications. This regex provides a strong
    // practical solution for most common and many less common valid email addresses.
    // For absolute certainty, a multi-step validation process including DNS checks
    // might be necessary. This regex does not fully support Internationalized
    // Domain Names (IDNs) in their full Unicode representation, as that would
    // significantly increase complexity and potential ReDoS risks.
    // This pattern is a widely accepted compromise for practical email validation.
    const std::string email_regex_pattern =
        R"(^(([^<>()[\]\\.,;:\s@"]+(\.[^<>()[\]\\.,;:\s@"]+)*)|(".+"))@((\[[0-9]{1,3}\.[0-9]{1,3}\.[0-9]{1,3}\.[0-9]{1,3}\])|(([a-zA-Z0-9](?:[a-zA-Z0-9-]{0,61}[a-zA-Z0-9])?\.)+[a-zA-Z]{2,})))$)";

    std::regex email_regex(email_regex_pattern);

    bool is_valid = std::regex_match(email, email_regex);

    return std::make_tuple(is_valid, email_regex_pattern);
}
